INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 11, 'theory', 'Quiz: tuples');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 11, 0, 'Which expression creates a tuple of one element?', '["(1)", "[1]", "(1,)", "{1}"]', 2, 'The comma creates a tuple: (1) is just a number in parentheses, while (1,) is a tuple of one element.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 11, 1, 't = (1, 2, 3). What happens on t[0] = 99?', '["t becomes (99, 2, 3)", "Python raises TypeError: a tuple can''t be changed", "A fourth element is added", "Nothing"]', 1, 'A tuple is immutable: assignment by index is impossible. It can be changed only by rebuilding it.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 11, 2, 'a, b = 1, 2; a, b = b, a. What are a and b?', '["a = 1, b = 2", "a = 2, b = 1", "a = 2, b = 2", "An error"]', 1, 'The right side is built in full before the assignment, so the values are swapped without a temporary variable.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 11, 3, 'What does a function with return min(nums), max(nums) return?', '["A list of two numbers", "Only the minimum", "A tuple of two numbers", "A dictionary"]', 2, 'The comma in return builds a tuple; the calling code can unpack it into two variables right away.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 11, 4, 'What do you get from first, *rest = [10, 20, 30]?', '["first = 10, rest = [20, 30]", "first = [10], rest = 20", "first = 10, rest = (20, 30)", "ValueError"]', 0, 'The star gathers all the extra elements into a list: first gets the beginning, rest gets the remainder.');
